input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?pname ?rate ?term ?type ?pay ?close ?amt WHERE {
?p a schema:MortgageLoan; schema:provider ?pr; schema:interestRate ?rate.
?pr schema:name ?pname.
OPTIONAL{?p schema:loanTerm ?t. ?t schema:value ?term} OPTIONAL{?p aw:rateType ?type}
OPTIONAL{?p aw:estimatedMonthlyPayment ?pm. ?pm schema:value ?pay} OPTIONAL{?p aw:estimatedClosingCosts ?cc. ?cc schema:value ?close}
OPTIONAL{?p aw:exampleLoanAmount ?la. ?la schema:value ?amt}
FILTER(?rate<=6.8)
} ORDER BY ?rate

